--radius-lg: 12px;   /* 실측 rounded-xl — 카드 */
--radius-xl: 16px;   /* 실측 rounded-2xl — 입력창·말풍선 */
--radius-2xl: 20px;  /* 실측 rounded-3xl — 바텀시트·모달 */
--radius-full: 9999px; /* 도구 칩·아이콘 버튼·전송 버튼 */
--shadow-none: none;
--shadow-sm: 0 1px 2px rgba(0,0,0,0.30);    /* 칩 hover */
--shadow-md: 0 2px 10px rgba(0,0,0,0.40);   /* 채팅 입력창 */
--shadow-lg: 0 8px 24px rgba(0,0,0,0.50);   /* 드롭다운·모델 선택 팝오버 */
--shadow-xl: 0 20px 48px rgba(0,0,0,0.60);  /* 모달·바텀시트 */
--duration-fast: 120ms;
--duration-base: 200ms;
--duration-slow: 360ms;   /* 원 모티프 확장·히어로 모션 (추정) */
--ease-out: cubic-bezier(0.22, 1, 0.36, 1);
--ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
}
