[data-theme="light"] {
  /* Primary - Inspire Red 9단계 */
  --color-primary-50:  #FFF5EC;  /* 실측 background_tint — 강조 행 배경 */
  --color-primary-100: #FFDFDB;  /* 실측 brand_base — 선택 칩 배경 */
  --color-primary-200: #FABAB9;  /* 실측 brand_secondary */
